-- Upgrade the first-party Website Builder to its bounded, draft-only v2 flow (#836).
-- Existing subscribed copies are replaced only when they still carry the exact stock v1
-- create-site shape. Any customised pipeline is left untouched; the stock definition it
-- replaces is archived under pipelinesReplaced for recovery.
UPDATE agents
SET config = json_set(
      CASE WHEN json_valid(config) THEN config ELSE '{} ' END,
      '$.pipelines.site-builder',
      json('{"name":"site-builder","params":{"place_id":{"type":"string","description":"Google Places id of the lead — the one required input; everything else is looked up."},"mcp_url":{"type":"string","description":"Website-builder MCP endpoint. Per-instance config: no server is hardcoded in the platform."},"template_slug":{"type":"string","description":"Optional designer-template preference. The builder lists the live catalogue and chooses a suitable returned slug."},"photo_limit":{"type":"number","description":"How many venue photos to pull into the gallery (default 4)."}},"steps":[{"tool":"http_request","bind":"details","inputs":{"method":"GET","url":"https://places.googleapis.com/v1/places/{{place_id}}","inputs":{"place_id":{"$param":"place_id"}},"headers":{"X-Goog-FieldMask":"id,displayName,formattedAddress,shortFormattedAddress,nationalPhoneNumber,websiteUri,googleMapsUri,rating,userRatingCount,editorialSummary,regularOpeningHours,primaryTypeDisplayName,photos,addressComponents"},"auth":{"mode":"api-key","key":{"in":"header","name":"X-Goog-Api-Key"}}}},{"tool":"slice","bind":"shots","inputs":{"items":{"$ref":"details.data.photos"},"limit":{"$param":"photo_limit"}}},{"tool":"http_request","bind":"photoPages","forEach":{"$ref":"shots.items"},"inputs":{"method":"GET","url":"https://places.googleapis.com/v1/{{photo}}/media","inputs":{"photo":{"$param":"item.name"}},"query":{"maxWidthPx":1200,"skipHttpRedirect":"true"},"auth":{"mode":"api-key","key":{"in":"query","name":"key"}},"responseMap":"photoUri"}},{"tool":"flatten","bind":"photos","inputs":{"items":{"$ref":"photoPages"},"path":"data"}},{"tool":"map","bind":"base","inputs":{"items":[{"d":{"$ref":"details.data"},"place_id":{"$param":"place_id"}}],"extract":{"name":"d.displayName.text","address":"d.formattedAddress","short_address":"d.shortFormattedAddress","phone":"d.nationalPhoneNumber","maps_url":"d.googleMapsUri","rating":"d.rating","reviews_count":"d.userRatingCount","blurb":"d.editorialSummary.text","hours":"d.regularOpeningHours.weekdayDescriptions","kind":"d.primaryTypeDisplayName.text","suburb":"d.addressComponents[types~=locality].longText","state":"d.addressComponents[types~=administrative_area_level_1].longText"},"keep":["place_id"],"derive":{"search_query":{"$format":"{{name}} {{suburb}} instagram facebook"},"ticket_title":{"$format":"Deploy the site for {{name}}"}}}},{"tool":"web_search","bind":"hits","inputs":{"query":{"$ref":"base.items.0.search_query"},"num":8}},{"tool":"extract_contacts","bind":"contacts","inputs":{"items":{"$ref":"hits"}}},{"tool":"map","bind":"biz","inputs":{"items":[{"b":{"$ref":"base.items.0"},"c":{"$ref":"contacts"},"photo_urls":{"$ref":"photos.items"}}],"extract":{"place_id":"b.place_id","name":"b.name","address":"b.address","short_address":"b.short_address","phone":"b.phone","maps_url":"b.maps_url","rating":"b.rating","reviews_count":"b.reviews_count","blurb":"b.blurb","hours":"b.hours","kind":"b.kind","suburb":"b.suburb","state":"b.state","ticket_title":"b.ticket_title","instagram":"c.instagram","facebook":"c.facebook","email":"c.email"},"keep":["photo_urls"]}},{"tool":"ai_generate","bind":"drafted","inputs":{"items":{"$ref":"biz.items"},"system":"You write short, plain, honest copy for a small local business''s first website. You are given ONLY facts scraped from Google Maps and public social profiles. Never invent a fact: no awards, no founding year, no staff names, no claims about quality, price or history you were not given. If you have little to work with, write less. Australian/British spelling. No emoji, no exclamation marks, no ''nestled in the heart of''. Reply with ONLY a JSON object — no prose, no code fence.","prompt":"Business facts:\n- Name: {{name}}\n- Type: {{kind}}\n- Address: {{address}}\n- Suburb: {{suburb}}, {{state}}\n- Phone: {{phone}}\n- Google rating: {{rating}} from {{reviews_count}} reviews\n- Google''s own summary: {{blurb}}\n- Opening hours: {{hours}}\n- Photo URLs (comma-separated, may be empty): {{photo_urls}}\n\nReturn JSON with exactly these keys:\n{\n  \"tagline\": \"6-10 words for the hero. What they are and where.\",\n  \"meta_description\": \"One sentence under 155 characters for search results.\",\n  \"about_html\": \"2-3 short sentences as HTML paragraphs. Only what the facts above support.\",\n  \"services_html\": \"A <ul> of 3-5 short items a customer would come here for, inferred from the business TYPE alone.\",\n  \"gallery_html\": \"For each photo URL above, one <img src=\\\"THE URL VERBATIM\\\" alt=\\\"...\\\" loading=\\\"lazy\\\"> wrapped in a <div class=\\\"grid\\\">. Copy each URL character-for-character; never shorten or invent one. Empty string if there are no photo URLs.\",\n  \"hours_line\": \"The opening hours as one readable line, or \\\"\\\" if unknown.\",\n  \"category\": \"one of: restaurant, cafe, salon, trades, retail, fitness, professional, health, education, creative, other\",\n  \"slug\": \"The business name as a URL slug: lowercase letters, numbers and hyphens ONLY, no leading/trailing hyphen, 3-40 characters. Add the suburb if the name alone is generic.\"\n}","as":"copy_json","maxTokens":900}},{"tool":"parse_json","bind":"copy","inputs":{"items":{"$ref":"drafted.items"},"field":"copy_json","as":"copy"}},{"tool":"mcp_call_tool","bind":"templates","inputs":{"url":{"$param":"mcp_url"},"tool":"list_templates","args":{}}},{"tool":"stringify_json","bind":"templateCatalog","inputs":{"value":{"$ref":"templates.data"},"pretty":true}},{"tool":"map","bind":"templateContext","inputs":{"items":[{"b":{"$ref":"biz.items.0"},"templates":{"$ref":"templateCatalog.text"},"preferred_template_slug":{"$param":"template_slug"}}],"extract":{"name":"b.name","kind":"b.kind","suburb":"b.suburb"},"keep":["templates","preferred_template_slug"]}},{"tool":"ai_generate","bind":"templateDraft","inputs":{"items":{"$ref":"templateContext.items"},"system":"Choose an appropriate existing designer template for a local business. Use only a template_slug literally present in the supplied catalogue. A preferred slug is a preference, not a mandate. Reply ONLY JSON.","prompt":"Business: {{name}} ({{kind}}), {{suburb}}.\nTemplate catalogue:\n{{templates}}\nPreferred template: {{preferred_template_slug}}\nReturn {\"template_slug\":\"exact catalogue slug\",\"reason\":\"short factual rationale\"}.","as":"template_json","maxTokens":300}},{"tool":"parse_json","bind":"templateChoice","inputs":{"items":{"$ref":"templateDraft.items"},"field":"template_json","as":"template"}},{"tool":"mcp_call_tool","bind":"site","inputs":{"url":{"$param":"mcp_url"},"tool":"create_site","args":{"template_slug":{"$ref":"templateChoice.items.0.template.template_slug"}}}},{"tool":"mcp_call_tool","bind":"sections","inputs":{"url":{"$param":"mcp_url"},"tool":"list_sections","args":{"session_id":{"$ref":"site.data.session_id"}}}},{"tool":"mcp_call_tool","bind":"sectionReads","forEach":{"$ref":"sections.data.sections"},"inputs":{"url":{"$param":"mcp_url"},"tool":"read_section","args":{"session_id":{"$ref":"site.data.session_id"},"section_id":{"$param":"item.id"}}}},{"tool":"stringify_json","bind":"sectionSource","inputs":{"value":{"$ref":"sectionReads"},"pretty":true}},{"tool":"mcp_call_tool","bind":"sectionContext","inputs":{"url":{"$param":"mcp_url"},"tool":"get_quality_report","args":{"session_id":{"$ref":"site.data.session_id"}}}},{"tool":"stringify_json","bind":"sectionDiagnostics","inputs":{"value":{"$ref":"sectionContext.data"},"pretty":true}},{"tool":"ai_generate","bind":"sectionPlan","inputs":{"items":[{"sections":{"$ref":"sectionSource.text"},"diagnostics":{"$ref":"sectionDiagnostics.text"}}],"system":"You improve an existing designer template. Use only section IDs in the supplied sections. Preserve layout and only return deliberate updates. Reply ONLY JSON.","prompt":"Existing sections:\n{{sections}}\nCurrent diagnostics:\n{{diagnostics}}\nReturn {\"sections\":[{\"id\":\"existing id\",\"content\":\"replacement inner HTML\",\"label\":\"optional\"}]}. Use no invented business claims.","as":"plan_json","maxTokens":1500}},{"tool":"parse_json","bind":"plannedSections","inputs":{"items":{"$ref":"sectionPlan.items"},"field":"plan_json","as":"plan"}},{"tool":"mcp_call_tool","bind":"meta","inputs":{"url":{"$param":"mcp_url"},"tool":"set_meta","args":{"session_id":{"$ref":"site.data.session_id"},"title":{"$ref":"copy.items.0.name"},"description":{"$ref":"copy.items.0.copy.meta_description"},"noindex":true}}},{"tool":"mcp_call_tool","bind":"contact","inputs":{"url":{"$param":"mcp_url"},"tool":"set_contact","args":{"session_id":{"$ref":"site.data.session_id"},"phone":{"$ref":"copy.items.0.phone"},"email":{"$ref":"copy.items.0.email"},"address":{"$ref":"copy.items.0.address"},"hours":{"$ref":"copy.items.0.copy.hours_line"}}}},{"tool":"mcp_call_tool","bind":"social","inputs":{"url":{"$param":"mcp_url"},"tool":"set_social","args":{"session_id":{"$ref":"site.data.session_id"},"instagram":{"$ref":"copy.items.0.instagram"},"facebook":{"$ref":"copy.items.0.facebook"}}}},{"tool":"mcp_call_tool","bind":"aboutSection","inputs":{"url":{"$param":"mcp_url"},"tool":"add_section","args":{"session_id":{"$ref":"site.data.session_id"},"type":"about","label":"About","content":{"$ref":"copy.items.0.copy.about_html"}}}},{"tool":"mcp_call_tool","bind":"servicesSection","inputs":{"url":{"$param":"mcp_url"},"tool":"add_section","args":{"session_id":{"$ref":"site.data.session_id"},"type":"features","label":"What we do","content":{"$ref":"copy.items.0.copy.services_html"}}}},{"tool":"mcp_call_tool","bind":"gallerySection","inputs":{"url":{"$param":"mcp_url"},"tool":"add_section","args":{"session_id":{"$ref":"site.data.session_id"},"type":"gallery","label":"Gallery","content":{"$ref":"copy.items.0.copy.gallery_html"}}}},{"tool":"mcp_call_tool","bind":"updatedTemplateSections","inputs":{"url":{"$param":"mcp_url"},"tool":"bulk_update_sections","args":{"session_id":{"$ref":"site.data.session_id"},"sections":{"$ref":"plannedSections.items.0.plan.sections"}}}},{"tool":"mcp_call_tool","bind":"quality1","inputs":{"url":{"$param":"mcp_url"},"tool":"get_quality_report","args":{"session_id":{"$ref":"site.data.session_id"}}}},{"tool":"map","bind":"qa1","inputs":{"items":[{"ready":{"$ref":"quality1.data.ready_for_human_review"}}],"keep":["ready"],"derive":{"needs_refinement":{"$cond":{"field":"ready","op":"falsy"},"then":true,"else":false},"passed":{"$cond":{"field":"ready","op":"truthy"},"then":true,"else":false}}}},{"tool":"stringify_json","bind":"quality1Text","inputs":{"value":{"$ref":"quality1.data"},"pretty":true}},{"tool":"ai_generate","bind":"refinementDraft","when":{"$ref":"qa1.items.0.needs_refinement"},"inputs":{"items":[{"sections":{"$ref":"sectionSource.text"},"quality":{"$ref":"quality1Text.text"}}],"system":"Repair only the reported static quality failures. Use only existing section IDs and preserve the designer template. Reply ONLY JSON.","prompt":"Quality report:\n{{quality}}\nCurrent sections:\n{{sections}}\nReturn {\"sections\":[{\"id\":\"existing id\",\"content\":\"replacement inner HTML\",\"label\":\"optional\"}]}. Make only changes that address the report.","as":"refinement_json","maxTokens":1400}},{"tool":"parse_json","bind":"refinement","when":{"$ref":"qa1.items.0.needs_refinement"},"inputs":{"items":{"$ref":"refinementDraft.items"},"field":"refinement_json","as":"plan"}},{"tool":"mcp_call_tool","bind":"refinedSections","when":{"$ref":"qa1.items.0.needs_refinement"},"inputs":{"url":{"$param":"mcp_url"},"tool":"bulk_update_sections","args":{"session_id":{"$ref":"site.data.session_id"},"sections":{"$ref":"refinement.items.0.plan.sections"}}}},{"tool":"mcp_call_tool","bind":"preview2","when":{"$ref":"qa1.items.0.needs_refinement"},"inputs":{"url":{"$param":"mcp_url"},"tool":"get_rendered_preview","args":{"session_id":{"$ref":"site.data.session_id"}}}},{"tool":"mcp_call_tool","bind":"quality2","when":{"$ref":"qa1.items.0.needs_refinement"},"inputs":{"url":{"$param":"mcp_url"},"tool":"get_quality_report","args":{"session_id":{"$ref":"site.data.session_id"}}}},{"tool":"map","bind":"finalGate","inputs":{"items":[{"initial_passed":{"$ref":"qa1.items.0.passed"},"refined_passed":{"$ref":"quality2.data.ready_for_human_review"}}],"keep":["initial_passed","refined_passed"],"derive":{"passed":{"$cond":{"field":"initial_passed","op":"truthy"},"then":true,"else":{"$cond":{"field":"refined_passed","op":"truthy"},"then":true,"else":false}},"needs_review":{"$cond":{"field":"initial_passed","op":"truthy"},"then":false,"else":{"$cond":{"field":"refined_passed","op":"truthy"},"then":false,"else":true}}}}},{"tool":"mcp_call_tool","bind":"preview","inputs":{"url":{"$param":"mcp_url"},"tool":"get_rendered_preview","args":{"session_id":{"$ref":"site.data.session_id"}}}},{"tool":"create_ticket","bind":"gate","when":{"$ref":"finalGate.items.0.passed"},"inputs":{"title":{"$ref":"copy.items.0.ticket_title"},"reasoning":"Built from this business''s Google Maps listing and public social profiles. Nothing is live: the draft is set to noindex and no domain is claimed. Approving deploys it. The copy is written from scraped facts, so read the preview first — especially anything that reads as a claim about the business.","action":"run_pipeline","config":{"pipeline":"site-deploy"},"params":{"place_id":{"$param":"place_id"},"mcp_url":{"$param":"mcp_url"},"session_id":{"$ref":"site.data.session_id"},"name":{"$ref":"copy.items.0.name"},"slug":{"$ref":"copy.items.0.copy.slug"},"category":{"$ref":"copy.items.0.copy.category"},"description":{"$ref":"copy.items.0.copy.meta_description"},"suburb":{"$ref":"copy.items.0.suburb"},"address":{"$ref":"copy.items.0.address"},"phone":{"$ref":"copy.items.0.phone"},"email":{"$ref":"copy.items.0.email"}}}},{"tool":"map","bind":"record","when":{"$ref":"finalGate.items.0.passed"},"inputs":{"items":{"$ref":"copy.items"},"keep":["place_id","name","address","phone","maps_url","suburb","state","instagram","facebook","email","photo_urls"],"derive":{"site_status":"awaiting_approval","site_session_id":{"$ref":"site.data.session_id"}}}},{"tool":"dedupe_upsert","bind":"stored","when":{"$ref":"finalGate.items.0.passed"},"inputs":{"items":{"$ref":"record.items"},"collection":"sites","key":"place_id","mode":"update","emit":"site.drafted"}},{"tool":"create_ticket","bind":"review","when":{"$ref":"finalGate.items.0.needs_review"},"inputs":{"title":"Static quality review required","reasoning":"One automatic refinement was attempted but the FWS static quality gate still failed. This noindex draft has no deploy action. Review the rendered preview and quality report, then repair it before requesting deployment approval.","params":{"place_id":{"$param":"place_id"},"session_id":{"$ref":"site.data.session_id"},"preview_url":{"$ref":"preview2.data.preview_url"},"quality_report":{"$ref":"quality2.data"}}}},{"tool":"map","bind":"reviewRecord","when":{"$ref":"finalGate.items.0.needs_review"},"inputs":{"items":{"$ref":"copy.items"},"keep":["place_id","name","address","phone","maps_url","suburb","state","instagram","facebook","email","photo_urls"],"derive":{"site_status":"needs_review","site_session_id":{"$ref":"site.data.session_id"}}}},{"tool":"dedupe_upsert","bind":"storedReview","when":{"$ref":"finalGate.items.0.needs_review"},"inputs":{"items":{"$ref":"reviewRecord.items"},"collection":"sites","key":"place_id","mode":"update","emit":"site.needs_review"}}],"sink":{"collection":"sites","keyField":"place_id"}}')
    ),
    updated_at = datetime('now')
WHERE slug = 'site-builder';

UPDATE agent_instances
SET config = json_set(
      json_set(
        json_set(
          CASE WHEN json_valid(config) THEN config ELSE '{}' END,
          '$.pipelinesReplaced',
          json(COALESCE(json_extract(CASE WHEN json_valid(config) THEN config ELSE '{}' END, '$.pipelinesReplaced'), '{}'))
        ),
        '$.pipelinesReplaced.site-builder',
        json(json_extract(CASE WHEN json_valid(config) THEN config ELSE '{}' END, '$.pipelines.site-builder'))
      ),
      '$.pipelines.site-builder',
      json((SELECT json_extract(CASE WHEN json_valid(a.config) THEN a.config ELSE '{}' END, '$.pipelines.site-builder')
              FROM agents a
             WHERE a.slug = 'site-builder'))
    ),
    updated_at = datetime('now')
WHERE agent_id IN (SELECT id FROM agents WHERE slug = 'site-builder')
  AND json_extract(CASE WHEN json_valid(config) THEN config ELSE '{}' END, '$.pipelines.site-builder.steps[10].bind') = 'site'
  AND json_extract(CASE WHEN json_valid(config) THEN config ELSE '{}' END, '$.pipelines.site-builder.steps[10].inputs.tool') = 'create_site'
  AND json_type(CASE WHEN json_valid(config) THEN config ELSE '{}' END, '$.pipelines.site-builder.steps[10].inputs.args.template_slug.$param') = 'text';

